// Shared starting point: atomic batch approval, without audit or idempotency.
package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"net/http"
	"sort"
	"strings"
)

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		for _, id := range ids {
			if strings.ContainsRune(id, 0) {
				return protocol.Result{}, false, &protocol.Rejection{Status: 404}
			}
		}

		// Compute requestHash: SHA-256 of "bulk-approve.v3\n" + sorted IDs formatted as "<length>:<id>"
		requestHash := computeRequestHash(ids)

		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)
		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		const operation = "bulk-approve.v3"

		// Check if this idempotency key has been used before with the same request hash.
		// Scope: operation + tenant + actor + key
		var existingHash string
		var existingResponse []byte
		err = tx.QueryRow(ctx, `
			SELECT "requestHash", response FROM "ActionRequest"
			WHERE operation=$1 AND "tenantId"=$2 AND "actorId"=$3 AND key=$4
		`, operation, u.Tenant, u.User, key).Scan(&existingHash, &existingResponse)
		if err == nil {
			// Key exists. Check if it's the same request.
			if existingHash == requestHash {
				// Same request: replay the result
				var result protocol.Result
				if err := json.Unmarshal(existingResponse, &result); err != nil {
					return protocol.Result{}, false, err
				}
				return result, true, nil
			} else {
				// Same key, different request: 409 conflict
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
		} else if err != pgx.ErrNoRows {
			return protocol.Result{}, false, err
		}
		// Key doesn't exist; proceed with approval

		// Fetch eligible purchases for approval (submitted, not created by approver)
		rows, err := tx.Query(ctx, `
			SELECT id FROM "Purchase"
			WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'
			ORDER BY id FOR UPDATE
		`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		eligible := []string{}
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}

		// All IDs must be eligible; otherwise reject entire batch
		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Update Purchase status
		tag, err := tx.Exec(ctx, `
			UPDATE "Purchase" SET status='approved'
			WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'
		`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Create ApprovalAudit record for each approved purchase
		for _, id := range eligible {
			_, err = tx.Exec(ctx, `
				INSERT INTO "ApprovalAudit"
				("tenantId", "purchaseId", "approvedBy", operation, "idempotencyKey", "fromStatus", "toStatus")
				VALUES ($1, $2, $3, $4, $5, $6, $7)
			`, u.Tenant, id, u.User, operation, key, "submitted", "approved")
			if err != nil {
				return protocol.Result{}, false, err
			}
		}

		// Create ActionRequest record for idempotency
		responseJSON, err := json.Marshal(protocol.Result{ApprovedIDs: eligible})
		if err != nil {
			return protocol.Result{}, false, err
		}

		_, err = tx.Exec(ctx, `
			INSERT INTO "ActionRequest"
			("tenantId", "actorId", operation, key, "requestHash", response)
			VALUES ($1, $2, $3, $4, $5, $6)
		`, u.Tenant, u.User, operation, key, requestHash, string(responseJSON))
		if err != nil {
			return protocol.Result{}, false, err
		}

		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}

		return protocol.Result{ApprovedIDs: eligible}, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

